async def act(page):
    """
    From the current "New Rule" page state, finish configuring the Actions so the
    rule gives 45% off all products for all customers and save the rule.

    This function uses accessibility-role-centric selectors (page.get_by_role)
    exclusively and places the final Save click as the last action.
    """
    # small pause to ensure UI is stable
    await page.wait_for_timeout(700)

    # 1) Ensure all Customer Groups are selected so the rule applies to all customers
    try:
        cg = page.get_by_role('listbox', name='Customer Groups *')
        if await cg.count() > 0:
            # Use exact visible labels from the accessibility tree
            await cg.nth(0).select_option([
                {'label': 'NOT LOGGED IN'},
                {'label': 'General'},
                {'label': 'Wholesale'},
                {'label': 'VIP Member'},
                {'label': 'Private Sales Member'},
            ])
            # short wait for the selection to register
            await page.wait_for_timeout(300)
    except Exception:
        # non-fatal: continue with other steps
        pass

    # 2) Open the Actions section/tab so we can set Apply/Discount fields
    opened_actions = False
    try:
        # Prefer a link named 'Actions'
        actions_link = page.get_by_role('link', name='Actions')
        if await actions_link.count() > 0:
            await actions_link.nth(0).click()
            opened_actions = True
        else:
            actions_tab = page.get_by_role('tab', name='Actions')
            if await actions_tab.count() > 0:
                await actions_tab.nth(0).click()
                opened_actions = True
            else:
                actions_btn = page.get_by_role('button', name='Actions')
                if await actions_btn.count() > 0:
                    await actions_btn.nth(0).click()
                    opened_actions = True
    except Exception:
        opened_actions = False

    # wait briefly for actions panel to render
    if opened_actions:
        await page.wait_for_timeout(600)
    else:
        # still wait a short time in case Actions section is already visible
        await page.wait_for_timeout(300)

    # 3) Set the 'Apply' combobox to a percent-of-product discount
    try:
        apply_candidates = [
            'Apply',
            'Apply To',
            'Apply (Action)',
            'simple_action',
            'Apply *'
        ]
        applied = False
        for name in apply_candidates:
            cb = page.get_by_role('combobox', name=name)
            if await cb.count() == 0:
                continue
            # try common visible labels
            for label in (
                'Percent of product price discount',
                'Percent of product price',
                'Percent of product price (discount)'
            ):
                try:
                    await cb.nth(0).select_option(label=label)
                    applied = True
                    break
                except Exception:
                    pass
            if applied:
                break
            # fallback to known values
            for val in ('by_percent', 'percent'):
                try:
                    await cb.nth(0).select_option(value=val)
                    applied = True
                    break
                except Exception:
                    pass
            if applied:
                break
        # final scanning fallback: try any combobox whose options mention 'percent'
        if not applied:
            all_cbs = page.get_by_role('combobox')
            if await all_cbs.count() > 0:
                for i in range(await all_cbs.count()):
                    c = all_cbs.nth(i)
                    try:
                        # attempt to select any option by label that contains 'percent'
                        # Note: select_option(label=..) will raise if label not found; we
                        # attempt a few likely label values first, then try value fallbacks.
                        for label in (
                            'Percent of product price discount',
                            'Percent of product price',
                        ):
                            try:
                                await c.select_option(label=label)
                                applied = True
                                break
                            except Exception:
                                pass
                        if applied:
                            break
                        for v in ('by_percent', 'percent'):
                            try:
                                await c.select_option(value=v)
                                applied = True
                                break
                            except Exception:
                                pass
                        if applied:
                            break
                    except Exception:
                        continue
    except Exception:
        pass

    # 4) Fill Discount Amount = 45 (try spinbutton then textbox)
    try:
        filled = False
        sb = page.get_by_role('spinbutton', name='Discount Amount')
        if await sb.count() > 0:
            await sb.nth(0).fill('45')
            filled = True
        else:
            tb = page.get_by_role('textbox', name='Discount Amount')
            if await tb.count() > 0:
                await tb.nth(0).fill('45')
                filled = True
        # fallback to any spinbutton
        if not filled:
            any_sb = page.get_by_role('spinbutton')
            if await any_sb.count() > 0:
                await any_sb.nth(0).fill('45')
                filled = True
        if not filled:
            any_tb = page.get_by_role('textbox')
            if await any_tb.count() > 0:
                await any_tb.nth(0).fill('45')
                filled = True
        await page.wait_for_timeout(200)
    except Exception:
        pass

    # 5) Ensure Free Shipping combobox (if present) is set to 'No'
    try:
        for fs_name in ('Free Shipping', 'Free Shipping for Matching Items', 'simple_free_shipping'):
            fs = page.get_by_role('combobox', name=fs_name)
            if await fs.count() == 0:
                continue
            try:
                await fs.nth(0).select_option(label='No')
            except Exception:
                try:
                    await fs.nth(0).select_option(value='0')
                except Exception:
                    pass
            break
    except Exception:
        pass

    # final small pause
    await page.wait_for_timeout(300)

    # 6) Click Save as the last action. Prefer the top-level 'Save' button present in the tree.
    save_clicked = False
    try:
        save_btn = page.get_by_role('button', name='Save')
        if await save_btn.count() > 0:
            await save_btn.nth(0).click()
            save_clicked = True
    except Exception:
        save_clicked = False

    if not save_clicked:
        # fallback: try 'Save and Continue Edit' then 'Save Rule'
        for lbl in ('Save and Continue Edit', 'Save Rule'):
            try:
                b = page.get_by_role('button', name=lbl)
                if await b.count() > 0:
                    await b.nth(0).click()
                    save_clicked = True
                    break
            except Exception:
                continue

    if save_clicked:
        # allow navigation / save to complete
        await page.wait_for_timeout(2000)
        return

    # If we reach here, we couldn't find a Save button - raise an explicit error
    raise RuntimeError('Unable to locate a Save button to finalize the price rule.')
